const regRelPath = "uploads/2026/10/03/reg-test-uuid.txt"
const regBody = "file-body-123"

// daoTransferLogSink 测试桥：transfer.Sink 接 dao（生产由 bootstrap 注入同形实现）
type daoTransferLogSink struct{ gormDB *gorm.DB }

func (s daoTransferLogSink) Create(ctx context.Context, e transfer.Entry) error {
	return dao.NewTransferLogRepository(s.gormDB).Create(ctx, &model.TransferLog{
		Operation: e.Operation, FileCodeID: e.FileCodeID, FileCode: e.Code,
		FileName: e.FileName, FileSize: e.FileSize, UserID: e.UserID,
		APIKeyID: e.APIKeyID, Username: e.Username, IP: e.IP, DurationMs: e.DurationMs,
	})
}

// newDownloadTestEnv 临时文件 DB（:memory: 多连接会各见独立库，异步日志会写不进）
// + 临时目录存储 + 注入 handler 单例 + 关闭下载令牌
func newDownloadTestEnv(t *testing.T) *gorm.DB {
	t.Helper()

	// DB 临时目录**自管**（不用 t.TempDir()）：t.TempDir() 的清理是 RemoveAll，
	// 而 sqlite 的 -wal/-shm 副文件在连接未关时仍可能被写回 —— RemoveAll
	// 递归删到一半、副文件重新出现，最终 rmdir 报 "directory not empty"
	// （实测约 1/40 偶发，2026-07-22 复核，与本仓其它改动无关）。
	// 这里改为：关连接 → 删目录（失败重试若干次）→ 仍失败则把残留内容打进
	// 日志，让这条用例**确定化**且失败可诊断（假红比没有这条断言更坏）。
	dbDir, err := os.MkdirTemp("", "bq-dl-*")
	require.NoError(t, err)
	g, err := gorm.Open(sqlite.Open(filepath.Join(dbDir, "test.db")), &gorm.Config{})
	require.NoError(t, err)
	t.Cleanup(func() {
		if sqlDB, dbErr := g.DB(); dbErr == nil {
			_ = sqlDB.Close() // 关连接会 checkpoint 并清掉 -wal/-shm 副文件
		}
		for i := 0; i < 10; i++ {
			if rmErr := os.RemoveAll(dbDir); rmErr == nil {
				return
			}
			time.Sleep(20 * time.Millisecond)
		}
		if entries, rdErr := os.ReadDir(dbDir); rdErr == nil {
			names := make([]string, 0, len(entries))
			for _, e := range entries {
				names = append(names, e.Name())
			}
			t.Logf("DB 临时目录删除失败，残留内容: %v", names)
		}
	})
	require.NoError(t, g.AutoMigrate(&model.FileCode{}, &model.TransferLog{}))
	transfer.SetSink(daoTransferLogSink{gormDB: g})

	dataPath := t.TempDir()
	fullPath := filepath.Join(dataPath, regRelPath)
	require.NoError(t, os.MkdirAll(filepath.Dir(fullPath), 0o755))
	require.NoError(t, os.WriteFile(fullPath, []byte(regBody), 0o644))

	// 先排水再撤 sink/删 TempDir：Record 异步落盘持有 DB 句柄，直删目录会竞争
	// （历史摇摆：readonly database / TempDir RemoveAll directory not empty）。
	//
	// ⚠️ 注册顺序决定执行顺序（t.Cleanup 是 LIFO：先注册的最后跑）：
	// 这条「排水」清理**必须注册在两个 t.TempDir() 之后**，否则它会晚于
	// TempDir 的 RemoveAll 执行 —— 异步写入还在跑就把目录删了，于是
	// "directory not empty"（实测约 1/12 偶发，2026-07-22）。
	// 期望的执行序：排水 → 删数据目录 → 关 DB 连接 → 删 DB 目录。
	//
	// 已知残余（2026-07-22 复核）：高并发下（-count≥40）仍有约 1/40 的
	// 偶发，残留报 "no such table: file_code_files" —— 来自 **admin 域的
	// 后台 janitor**（app/admin/janitor.go，其 CleanupStaleUploads 会动
	// 存储目录），其生命周期未与本测试绑定。CI 跑 -count=1，命中概率极低；
	// 要彻底收口需给 janitor 补可停止的 ctx 并在本包用例里停掉它。
	t.Cleanup(func() { transfer.Flush(3 * time.Second); transfer.SetSink(nil) })

	// 同包直接注入 handler 懒加载单例；关闭下载令牌（conf 零值 Enabled=false）
	conf.SetGlobalConfig(&conf.AppConfiguration{})
	shareSvc = shareService.NewService(g, "http://test.local", storage.NewStorageService(&storage.StorageConfig{
		Type:     storage.StorageTypeLocal,
		DataPath: dataPath,
	}))
	t.Cleanup(func() {
		shareSvc = nil
		conf.SetGlobalConfig(nil)
	})
	return g
}

